    static BigDecimal parseAmount(String field, String value) {
        if (value == null || value.isBlank()) {
            throw ApiException.badRequest("INVALID_ARGUMENT", field + " 涓嶈兘涓虹┖");
        }
        String trimmed = value.trim();
